sys_script_client.script:
function onLoad() {

    //fields from Manager section

    var readonlyFields = ["emp_time_in_pos", "inc_type_occ", "mng_inc_desc", "mng_desc_injury", "correct_meas_imp_date", "implementation_date", "dir_cause_injury", "inc_req_prot_equip", "brief_description_and_estimated_cost", "date_and_time_of_occurrence", "employee_gender", "direct_causes_of_hazardous_occurrence", "supplementary_preventative_measures", "additional_investigation_notes", "emp_age", "user", "emp_work_start", "emp_work_end", "inc_training_prov", "training_spec", "weather", "no_correct_meas_reas", "inc_witnesses", "was_the_employee_on_modified_duties_at_the_time_of_the_incident", "does_the_employee_now_require_modified_duties_as_a_result_of_this_injury", "did_the_employee_consult_a_healthcare_professional_as_a_result_of_this_injury", "did_this_incident_result_in_an_injury", "inc_related_illness", "inc_related_post_exp"];

	//Roles allowed to write to Manager section field
	var allowedRoles = "x_hccc_hoc_ohs.advisor,admin";
    var answer = true;


    var loggedUser = g_user.userID.toString();
//	alert('loggeduser'+g_user.userName);
    var currentManager = g_form.getValue("manager_name");
	//alert('currentManager'+currentManager);

	//alert(g_user.hasRoleFromList(allowedRoles));


    if ((loggedUser == currentManager) || g_user.hasRoleFromList(allowedRoles)) {
        answer = false;

    }
//	alert(answer);

    for (var i = 0; i < readonlyFields.length; i++) {	

        if (g_form.hasField(readonlyFields[i])) {           
            g_form.setReadOnly(readonlyFields[i], answer);
        }

    }


}
